class Solution {
    int m, n;
    int[] parent, size;
    int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};

    // Union-Find find with path compression
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    // Union two sets
    void union(int x, int y) {
        int rootX = find(x), rootY = find(y);
        if (rootX == rootY) return;
        if (size[rootX] < size[rootY]) {
            parent[rootX] = rootY;
            size[rootY] += size[rootX];
        } else {
            parent[rootY] = rootX;
            size[rootX] += size[rootY];
        }
    }

    // Get size of the set that x belongs to
    int getSize(int x) {
        return size[find(x)];
    }

    public int[] hitBricks(int[][] grid, int[][] hits) {
        m = grid.length;
        n = grid[0].length;
        parent = new int[m*n+1]; // extra one for virtual top
        size = new int[m*n+1];
        for (int i = 0; i < m*n+1; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        // Copy grid and apply hits by marking bricks to be removed
        int[][] copy = new int[m][n];
        for (int i = 0; i < m; i++) 
            System.arraycopy(grid[i], 0, copy[i], 0, n);
        for (int[] hit : hits) {
            int r = hit[0], c = hit[1];
            if (copy[r][c] == 1) copy[r][c] = 0;
        }

        // Connect stable bricks in the copy grid
        // Virtual top node index = m*n
        for (int c = 0; c < n; c++) {
            if (copy[0][c] == 1) union(c, m*n);
        }
        for (int r = 1; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (copy[r][c] == 1) {
                    // connect with up if brick
                    if (copy[r-1][c] == 1) union(r*n+c, (r-1)*n+c);
                    // connect with left if brick
                    if (c > 0 && copy[r][c-1] == 1) union(r*n+c, r*n+c-1);
                }
            }
        }

        int hitsLen = hits.length;
        int[] res = new int[hitsLen];

        // Process hits in reverse order
        for (int i = hitsLen - 1; i >= 0; i--) {
            int r = hits[i][0], c = hits[i][1];
            // If original grid had no brick, nothing falls
            if (grid[r][c] == 0) {
                res[i] = 0;
                continue;
            }
            // Before adding back the brick, record stable size
            int prevStable = getSize(m*n);

            // Add back the brick
            copy[r][c] = 1;

            // If brick is in top row, connect to virtual top
            int idx = r*n + c;
            if (r == 0) union(idx, m*n);

            // Connect with neighbors if they have bricks
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && copy[nr][nc] == 1) {
                    union(idx, nr*n + nc);
                }
            }

            // After union, get new stable size
            int newStable = getSize(m*n);

            // Number of bricks that fell = increase in stable bricks - 1 (the brick we just added)
            res[i] = Math.max(0, newStable - prevStable - 1);
        }

        return res;
    }
